
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_mscan_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_mscan", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.884492320724279e+00, -4.785600051344510e+00, -4.646985876384186e+00, -4.454880792226411e+00, -4.192919735557256e+00, -3.843850167944057e+00, -3.393648817428967e+00, -2.838945001368129e+00, -2.196877415376505e+00, -1.503877918820119e+00, -8.475214193656494e-01, -6.215068426652552e-01, -6.114131227608552e-01, -5.088748774925366e-01, -3.340122362753404e-01, -1.733272213188509e-01, -7.192961898464344e-02, -1.994606381688836e-02, -2.735046730212388e-03, -1.272314678994366e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


